contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public {
        require(c.owner() == address(this), "not owner");
        require(amount > 0, "zero amount");
        (, , uint40 lastUpd, ) = c.rewardData(address(this));
        require(lastUpd == 0, "token already added");
        c.addReward(address(this));
        c.setRewardDistributor(address(this));
        c.notifyRewardAmount(address(this), amount);
        uint40 finish = c.rewardPeriodFinish(address(this));
        assert(finish == uint40(block.timestamp) + uint40(c.DURATION()));
    }
    fallback() external payable {
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }
    receive() external payable {}
}

